"""Frontier AI Incident Ledger — loader, validator, basic stats.

Usage:
    python ledger.py schema.csv            # validate and print summary
    python ledger.py schema.csv --json     # machine-readable summary

Pure standard library; no dependencies.
"""
from __future__ import annotations

import csv
import json
import statistics
import sys
from datetime import date

CATEGORIES = {"WEIGHTS", "UPLIFT", "AUTONOMY", "BYPASS", "SURPRISE", "EVAL", "GOVERNANCE", "OTHER"}
CHANNELS = {"self", "third-party", "press", "leak"}
CONFIDENCE = {"high", "medium", "low"}
REQUIRED = ["id", "category", "developer", "disclosure_date", "disclosure_channel", "summary", "sources", "confidence"]


def parse_date(s: str) -> date | None:
    s = s.strip().lstrip("~")
    if not s:
        return None
    return date.fromisoformat(s)


def validate(rows: list[dict]) -> list[str]:
    errors: list[str] = []
    seen: set[str] = set()
    for i, r in enumerate(rows, start=2):  # header is line 1
        rid = r.get("id", "").strip()
        if rid in seen:
            errors.append(f"line {i}: duplicate id {rid}")
        seen.add(rid)
        for f in REQUIRED:
            if not r.get(f, "").strip():
                errors.append(f"line {i} ({rid}): missing required field '{f}'")
        if r.get("category") not in CATEGORIES:
            errors.append(f"line {i} ({rid}): bad category '{r.get('category')}'")
        if r.get("disclosure_channel") not in CHANNELS:
            errors.append(f"line {i} ({rid}): bad disclosure_channel '{r.get('disclosure_channel')}'")
        if r.get("confidence") not in CONFIDENCE:
            errors.append(f"line {i} ({rid}): bad confidence '{r.get('confidence')}'")
        for f in ("event_date", "awareness_date", "disclosure_date", "developer_ack_date"):
            try:
                parse_date(r.get(f, ""))
            except ValueError:
                errors.append(f"line {i} ({rid}): unparseable {f} '{r.get(f)}'")
        # latency consistency
        try:
            a, d = parse_date(r.get("awareness_date", "")), parse_date(r.get("disclosure_date", ""))
            if a and d:
                computed = (d - a).days
                stated = r.get("latency_days", "").strip()
                if stated and int(stated) != computed:
                    errors.append(f"line {i} ({rid}): latency_days {stated} != computed {computed}")
                if computed < 0:
                    errors.append(f"line {i} ({rid}): disclosure before awareness")
        except ValueError:
            pass
    return errors


def summarise(rows: list[dict]) -> dict:
    real = [r for r in rows if not r["id"].startswith("HT-EXAMPLE")]
    latencies = []
    for r in real:
        a, d = parse_date(r.get("awareness_date", "")), parse_date(r.get("disclosure_date", ""))
        if a and d:
            latencies.append((d - a).days)
    by = lambda key: {k: sum(1 for r in real if r.get(key) == k) for k in sorted({r.get(key) for r in real})}
    return {
        "entries": len(real),
        "by_category": by("category"),
        "by_channel": by("disclosure_channel"),
        "by_developer": by("developer"),
        "latency_days": {
            "n": len(latencies),
            "median": statistics.median(latencies) if latencies else None,
            "mean": round(statistics.mean(latencies), 1) if latencies else None,
            "max": max(latencies) if latencies else None,
        },
        "share_self_disclosed": (round(sum(1 for r in real if r.get("disclosure_channel") == "self") / len(real), 2) if real else None),
    }


def main(argv: list[str]) -> int:
    if len(argv) < 2:
        print(__doc__)
        return 2
    with open(argv[1], newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))
    errors = validate(rows)
    summary = summarise(rows)
    if "--json" in argv:
        print(json.dumps({"errors": errors, "summary": summary}, indent=2))
    else:
        for e in errors:
            print("ERROR:", e)
        print(f"{len(rows)} rows, {len(errors)} validation errors")
        print(json.dumps(summary, indent=2))
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
